import {mkdirSync,mkdtempSync,readFileSync,writeFileSync,symlinkSync} from 'node:fs';
import {join} from 'node:path';
import {sourceHash} from '../scripts/quality-inventory';
const root=process.cwd(), work=mkdtempSync(join(root,'.git','b11-holder-mutation-'));
const testPath='tests/helpers/test-database.test.ts';
const paths=[testPath,'tests/helpers/test-database.ts','tests/helpers/owned-test-directory.ts','tests/test-setup.ts'];
const source=readFileSync(testPath,'utf8');
const needle='if(child.exitCode===null&&child.signalCode===null)child.kill();';
if(source.split(needle).length!==2)throw Error('Ambiguous teardown decision');
mkdirSync(join(work,'tests/helpers'),{recursive:true});
symlinkSync(join(root,'src'),join(work,'src'),'junction');
for(const path of paths.slice(0,3))writeFileSync(join(work,path),path===testPath?source.replace(needle,'void child;'):readFileSync(path,'utf8'));
writeFileSync(join(work,'bunfig.toml'),'[test]\ncoverage = false\npreload = ['+JSON.stringify(join(root,'tests/test-setup.ts'))+']\n');
const child=Bun.spawnSync([process.execPath,'test','--timeout','15000',testPath,'--test-name-pattern','interrupted lock-holder callback'],{cwd:work,stdout:'pipe',stderr:'pipe',timeout:45000});
const output=new TextDecoder().decode(child.stdout)+new TextDecoder().decode(child.stderr);
const killed=child.exitCode===1&&output.includes('(fail)')&&output.includes('Expected: "SIGTERM"')&&output.includes('Received: "SIGKILL"');
writeFileSync('.git/b11-holder-mutation.json',JSON.stringify({runtime:Bun.version,sourceInputs:paths.map(path=>({path,sourceHash:sourceHash(readFileSync(path,'utf8'))})),work,needle,replacement:'void child;',command:[process.execPath,'test','--timeout','15000',testPath,'--test-name-pattern','interrupted lock-holder callback'],exit:child.exitCode,status:killed?'KILLED':'UNRESOLVED',output,probeSource:readFileSync('.git/b11-holder-mutation.ts','utf8'),scope:'Deliberate omitted termination in generated driver only; the unchanged child watchdog remains active. Parent waits for terminal child test process before recording.'},null,2)+'\n');
console.log(JSON.stringify({exit:child.exitCode,status:killed?'KILLED':'UNRESOLVED',output:output.slice(-1800)}));
if(!killed)process.exitCode=1;

