 if(record.status!=='KILLED'||record.exit!==1||record.recovery.some((x:any)=>x.status.startsWith('retained')))throw Error('Unresolved fault '+record.id);
 map.addFileCoverage({path,...faults.driverMaps,...record.driverCounters});
}
