import {readFileSync,writeFileSync} from 'node:fs';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {sourceHash,discoverInventory,validateInventory} from '../scripts/quality-inventory';
const root='.planning/memory-resilience/', read=(p:string)=>JSON.parse(readFileSync(p,'utf8'));
const hash=(p:string)=>sourceHash(readFileSync(p,'utf8'));
const assert=(x:unknown,m:string)=>{if(!x)throw Error(m);};
const path=root+'evidence/B11.1-holder-proof.json', packet=read(path);
for(const input of [...packet.sourceInputs,...packet.artifacts])assert(hash(input.path)===input.sourceHash,'Stale '+input.path);
const catalog=discoverInventory(process.cwd());
assert(JSON.stringify(catalog)===JSON.stringify(read(root+'executable-catalog.json'))&&!validateInventory(catalog,read(root+'quality-classifications.json')).length,'Stale inventory');
const platforms=read(root+'evidence/B11.1-holder-platforms.json'), faults=read(root+'evidence/B11.1-holder-faults.json');
const exactKeys=(left:object,right:object)=>JSON.stringify(Object.keys(left).sort())===JSON.stringify(Object.keys(right).sort());
function validateCounters(data:any,maps:any){
 for(const [counter,map] of [['s','statementMap'],['f','fnMap'],['b','branchMap']]){
  assert(exactKeys(data[counter!],maps[map!]),'Missing/extra counter');
  for(const [id,value] of Object.entries(data[counter!])){
   const counts=counter==='b'?value as number[]:[value];
   if(counter==='b')assert(counts.length===maps.branchMap[id].locations.length,'Wrong branch count');
   assert(counts.every((x:any)=>Number.isSafeInteger(x)&&x>=0),'Malformed counter');
  }
 }
}
for(const p of [platforms.windows,platforms.linux])for(const input of p.sourceInputs)assert(hash(input.path)===input.sourceHash,'Stale platform source');
for(const input of faults.sourceInputs)assert(hash(input.path)===input.sourceHash,'Stale fault source');
for(const row of packet.diagnostics.files){
 const data=[platforms.windows,platforms.linux].map(p=>Object.values(p.rawCoverage).find((x:any)=>x.path.replaceAll('\\','/').endsWith('/'+row.path)) as any);
 for(const mapName of ['statementMap','fnMap','branchMap'])assert(JSON.stringify(data[0][mapName])===JSON.stringify(data[1][mapName]),'Platform map mismatch');
 const map=createCoverageMap({});
 for(const raw of data){validateCounters(raw,raw);map.addFileCoverage({...raw,path:row.path});}
 if(row.path==='tests/helpers/test-database.test.ts'){
  for(const name of ['statementMap','fnMap','branchMap'])assert(JSON.stringify(data[0][name])===JSON.stringify(faults.driverMaps[name]),'Fault map mismatch');
  assert(faults.records.length===11,'Missing fault');
  for(const fault of faults.records){
   assert(fault.status==='KILLED'&&fault.exit===1&&!fault.recovery.some((x:any)=>x.status.startsWith('retained')),'Unresolved fault');
   validateCounters(fault.driverCounters,faults.driverMaps);
   map.addFileCoverage({path:row.path,...faults.driverMaps,...fault.driverCounters});
  }
 }
 const summary=map.fileCoverageFor(row.path).toSummary().data;
 assert(JSON.stringify(summary)===JSON.stringify(row.metrics),'Summary mismatch');
 for(const key of ['lines','statements','functions','branches'])assert(summary[key].total>0&&summary[key].pct>=(key==='branches'?100:95),'Below diagnostic floor');
}
const ledger=read(root+'work-items.json'), ids=new Map<string,any>(ledger.items.map((x:any)=>[x.id,x])), done=new Set<string>();
function visit(id:string,stack=new Set<string>()){assert(ids.has(id)&&!stack.has(id),'Invalid dependency');if(done.has(id))return;for(const dep of ids.get(id).depends_on)visit(dep,new Set([...stack,id]));done.add(id);}
assert(ids.size===218&&ids.size===ledger.items.length,'Ledger changed');for(const id of ids.keys())visit(id);
assert(ledger.current_item==='B11.2'&&ledger.items.filter((x:any)=>x.status==='active').map((x:any)=>x.id).join()==='B11.2','Unexpected active task');
assert(ids.get('B11.1').status==='blocked'&&ids.get('B04').status==='blocked'&&ids.get('B05').status==='pending','Premature acceptance');
assert(packet.checks[1].exit===-1&&packet.checks[1].classification.includes('unverified'),'Linux launch failure lost');
packet.validation={command:'bun .git/b11-holder-validate.ts',exit:0,result:'Live source/artifact inventory; exact platform/fault maps and complete nonnegative counters; recomputed scoped metric floors; eleven faults; retained Linux launch failure; acyclic 218-item ledger with only B11.2 active.',source:readFileSync('.git/b11-holder-validate.ts','utf8'),inventoryOutput:readFileSync('.git/b11-holder-inventory.txt','utf8')};
writeFileSync(path,JSON.stringify(packet,null,2)+'\n');console.log(packet.validation.result);
